import { webSocketFn } from "./src/webSocket" with { type: "ref" };
import { seedDevData } from "./src/dbSeeds" with { type: "ref" };

import { getChannels, getChannel, getChannelMessages } from "./src/queries" with { type: "ref" };
import { createChannel, createMessage, markAsRead } from "./src/actions" with { type: "ref" };

export default app({
  name: "realTimeChat",
  title: "Real-Time Chat App",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthSucceededRedirectTo: "/",
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  db: {
    seeds: [seedDevData],
