import { type WebSocketDefinition } from "wasp/server/webSocket";

// Global reference to the io server instance
let ioInstance: any = null;

export const getIoInstance = () => {
  return ioInstance;
};

// channelId -> Map<username, Set<socketId>>
const channelUserSockets = new Map<number, Map<string, Set<string>>>();

// socketId -> Set<channelId>
const socketChannels = new Map<string, Set<number>>();

export const webSocketFn: WebSocketDefinition = (io, _context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    const user = socket.data.user;
    const username = user?.username;

    if (!username) {
      return;
    }

    socket.on("joinChannel", ({ channelId }: { channelId: number }) => {
      // socket joins the room
      socket.join(`channel-${channelId}`);

      // Track socket channels
      if (!socketChannels.has(socket.id)) {
        socketChannels.set(socket.id, new Set());
      }
      socketChannels.get(socket.id)!.add(channelId);

      // Track channel user sockets
      if (!channelUserSockets.has(channelId)) {
        channelUserSockets.set(channelId, new Map());
      }
      const userSocketsMap = channelUserSockets.get(channelId)!;
      if (!userSocketsMap.has(username)) {
        userSocketsMap.set(username, new Set());
      }
      userSocketsMap.get(username)!.add(socket.id);

      // Broadcast active users
      const activeUsers = Array.from(userSocketsMap.keys());
      io.to(`channel-${channelId}`).emit("activeUsers", activeUsers);
    });

    socket.on("leaveChannel", ({ channelId }: { channelId: number }) => {
      socket.leave(`channel-${channelId}`);

      // Remove from socket channels
      if (socketChannels.has(socket.id)) {
        socketChannels.get(socket.id)!.delete(channelId);
      }

      // Remove from channel user sockets
      if (channelUserSockets.has(channelId)) {
        const userSocketsMap = channelUserSockets.get(channelId)!;
        if (userSocketsMap.has(username)) {
          userSocketsMap.get(username)!.delete(socket.id);
          if (userSocketsMap.get(username)!.size === 0) {
            userSocketsMap.delete(username);
          }
        }

        // Broadcast updated active users
        const activeUsers = Array.from(userSocketsMap.keys());
        io.to(`channel-${channelId}`).emit("activeUsers", activeUsers);
      }
    });

    socket.on("typing", ({ channelId, isTyping }: { channelId: number; isTyping: boolean }) => {
      // Broadcast to room channel-${channelId} excluding the sender
      socket.to(`channel-${channelId}`).emit("typing", { username, isTyping });
    });

    socket.on("disconnect", () => {
      const channels = socketChannels.get(socket.id);
      if (channels) {
        for (const channelId of channels) {
          if (channelUserSockets.has(channelId)) {
            const userSocketsMap = channelUserSockets.get(channelId)!;
            if (userSocketsMap.has(username)) {
              userSocketsMap.get(username)!.delete(socket.id);
              if (userSocketsMap.get(username)!.size === 0) {
                userSocketsMap.delete(username);
              }
            }

            // Broadcast updated active users
            const activeUsers = Array.from(userSocketsMap.keys());
            io.to(`channel-${channelId}`).emit("activeUsers", activeUsers);
          }
        }
        socketChannels.delete(socket.id);
      }
    });
  });
};

import { type GetChannels, type GetChannel, type GetChannelMessages } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getChannels: GetChannels<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Channel.findMany();
};

export const getChannel: GetChannel<{ id: number }, any> = async ({ id }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const channel = await context.entities.Channel.findUnique({
    where: { id },
  });
  if (!channel) {
    throw new HttpError(404, "Channel not found");
  }
  return channel;
};

export const getChannelMessages: GetChannelMessages<{ channelId: number }, any> = async ({ channelId }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const messages = await context.entities.Message.findMany({
    where: { channelId },
    orderBy: { createdAt: "asc" },
    include: {
      sender: {
        select: {
          id: true,
          username: true,
        },
      },
      readReceipts: {
        include: {
          user: {
            select: {
              id: true,
              username: true,
            },
          },
        },
      },
    },
  });

  return messages;
};

import { type CreateChannel, type CreateMessage, type MarkAsRead } from "wasp/server/operations";
import { HttpError } from "wasp/server";
import { getIoInstance } from "./webSocket";

export const createChannel: CreateChannel<{ name: string }, any> = async ({ name }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const existing = await context.entities.Channel.findUnique({
    where: { name },
  });
  if (existing) {
    throw new HttpError(400, "Channel already exists");
  }

  return context.entities.Channel.create({
    data: { name },
  });
};

export const createMessage: CreateMessage<{ channelId: number; content: string }, any> = async ({ channelId, content }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const message = await context.entities.Message.create({
    data: {
      content,
      senderId: context.user.id,
      channelId,
    },
    include: {
      sender: {
        select: {
          id: true,
          username: true,
        },
      },
    },
  });

  // Automatically create or update the sender's ReadReceipt
  await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    update: {
      lastReadMessageId: message.id,
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId: message.id,
    },
  });

  const io = getIoInstance();
  if (io) {
    io.to(`channel-${channelId}`).emit("messageCreated", message);
  }

  return message;
};

export const markAsRead: MarkAsRead<{ channelId: number; lastReadMessageId: number }, any> = async ({ channelId, lastReadMessageId }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const receipt = await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    update: {
      lastReadMessageId,
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId,
    },
  });

  const io = getIoInstance();
  if (io) {
    io.to(`channel-${channelId}`).emit("readReceiptUpdated", {
      userId: context.user.id,
      username: context.user.username,
      lastReadMessageId,
    });
  }

  return receipt;
};

