import { useState, useEffect, useRef } from "react";
import { useParams, Link } from "react-router";
import { useQuery, getChannel, getChannelMessages, createMessage, markAsRead } from "wasp/client/operations";
import { useAuth } from "wasp/client/auth";
import { useSocket, useSocketListener } from "wasp/client/webSocket";

export function ChannelPage() {
  const { id } = useParams<{ id: string }>();
  const channelId = Number(id);

  const { data: user } = useAuth();
  const { data: channel, isLoading: isChannelLoading, error: channelError } = useQuery(getChannel, { id: channelId });
  const { data: messagesQueryData, isLoading: isMessagesLoading, error: messagesError } = useQuery(getChannelMessages, { channelId });

  const [messages, setMessages] = useState<any[]>([]);
  const [messageContent, setMessageContent] = useState("");
  const [activeUsers, setActiveUsers] = useState<string[]>([]);
  const [typingUsers, setTypingUsers] = useState<Record<string, number>>({});
  const [readReceiptsMap, setReadReceiptsMap] = useState<Map<number, { username: string; lastReadMessageId: number }>>(new Map());

  const { socket, isConnected } = useSocket();

  const [isCurrentlyTyping, setIsCurrentlyTyping] = useState(false);
  const [typingTimeoutId, setTypingTimeoutId] = useState<any>(null);

  // Initialize messages and read receipts map from query data
  useEffect(() => {
    if (messagesQueryData) {
      setMessages(messagesQueryData);

      const initialReceipts = new Map<number, { username: string; lastReadMessageId: number }>();
      messagesQueryData.forEach((msg: any) => {
        msg.readReceipts?.forEach((receipt: any) => {
          const existing = initialReceipts.get(receipt.userId);
          if (!existing || receipt.lastReadMessageId > existing.lastReadMessageId) {
            initialReceipts.set(receipt.userId, {
              username: receipt.user.username,
              lastReadMessageId: receipt.lastReadMessageId,
            });
          }
        });
      });
      setReadReceiptsMap(initialReceipts);
    }
  }, [messagesQueryData]);

  // Join channel room on socket connect/channelId change
  useEffect(() => {
    if (socket && !isNaN(channelId)) {
      socket.emit("joinChannel", { channelId });
      return () => {
        socket.emit("leaveChannel", { channelId });
      };
    }
  }, [socket, channelId]);

  // Mark message as read helper
  const lastMarkedReadIdRef = useRef<number | null>(null);
  const markMessageAsRead = async (messageId: number) => {
    if (lastMarkedReadIdRef.current === messageId) return;
    lastMarkedReadIdRef.current = messageId;
    try {
      await markAsRead({ channelId, lastReadMessageId: messageId });
    } catch (err) {
      console.error("Failed to mark message as read:", err);
    }
  };

  // Automatically mark latest message as read when messages update
  useEffect(() => {
    if (messages.length > 0) {
      const latestMessage = messages[messages.length - 1];
      markMessageAsRead(latestMessage.id);
    }
  }, [messages]);

  // Listen to active users list
  useSocketListener("activeUsers", (usernames: string[]) => {
    setActiveUsers(usernames);
  });

  // Listen to typing status
  useSocketListener("typing", ({ username, isTyping }: { username: string; isTyping: boolean }) => {
    setTypingUsers((prev) => {
      const next = { ...prev };
      if (isTyping) {
        next[username] = Date.now();
      } else {
        delete next[username];
      }
      return next;
    });
  });

  // Clean up typing indicators that are inactive for more than 3 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setTypingUsers((prev) => {
        const now = Date.now();
        const next = { ...prev };
        let changed = false;
        for (const username of Object.keys(next)) {
          if (now - next[username] > 3000) {
            delete next[username];
            changed = true;
          }
        }
        return changed ? next : prev;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Listen to new messages
  useSocketListener("messageCreated", (newMessage: any) => {
    if (newMessage.channelId === channelId) {
      setMessages((prev) => {
        if (prev.some((m) => m.id === newMessage.id)) return prev;
        return [...prev, newMessage];
      });
      markMessageAsRead(newMessage.id);
    }
  });

  // Listen to read receipt updates
  useSocketListener("readReceiptUpdated", ({ userId, username, lastReadMessageId }: { userId: number; username: string; lastReadMessageId: number }) => {
    setReadReceiptsMap((prev) => {
      const next = new Map(prev);
      const existing = next.get(userId);
      if (!existing || lastReadMessageId > existing.lastReadMessageId) {
        next.set(userId, { username, lastReadMessageId });
      }
      return next;
    });
  });

  const handleKeyDown = () => {
    if (!isCurrentlyTyping && socket) {
      setIsCurrentlyTyping(true);
      socket.emit("typing", { channelId, isTyping: true });
    }

    if (typingTimeoutId) {
      clearTimeout(typingTimeoutId);
    }

    const timeoutId = setTimeout(() => {
      setIsCurrentlyTyping(false);
      socket?.emit("typing", { channelId, isTyping: false });
    }, 3000);
    setTypingTimeoutId(timeoutId);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!messageContent.trim()) return;

    if (typingTimeoutId) {
      clearTimeout(typingTimeoutId);
      setTypingTimeoutId(null);
    }
    if (isCurrentlyTyping && socket) {
      setIsCurrentlyTyping(false);
      socket.emit("typing", { channelId, isTyping: false });
    }

    try {
      await createMessage({ channelId, content: messageContent.trim() });
      setMessageContent("");
    } catch (err) {
      console.error("Failed to send message:", err);
    }
  };

  const getReadersForMessage = (message: any) => {
    const readers: string[] = [];
    readReceiptsMap.forEach((receipt, userId) => {
      if (userId !== message.senderId && receipt.lastReadMessageId >= message.id) {
        readers.push(receipt.username);
      }
    });
    return readers;
  };

  if (isChannelLoading || isMessagesLoading) {
    return <p>Loading...</p>;
  }

  if (channelError || messagesError) {
    return <p style={{ color: "red" }}>Error loading channel or messages</p>;
  }

  if (!channel) {
    return <p>Channel not found</p>;
  }

  return (
    <div style={{ padding: "20px", maxWidth: "800px", margin: "0 auto", display: "flex", flexDirection: "column", gap: "20px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h1 data-testid="channel-title">{channel.name}</h1>
        <Link data-testid="back-to-channels" to="/">
          Back to Channels
        </Link>
      </div>

      <div style={{ display: "flex", gap: "20px" }}>
        {/* Messages and Input Area */}
        <div style={{ flex: 3, display: "flex", flexDirection: "column", gap: "10px" }}>
          {/* Messages list */}
          <div
            data-testid="messages-list"
            style={{
              border: "1px solid #ccc",
              borderRadius: "4px",
              padding: "15px",
              height: "400px",
              overflowY: "scroll",
              display: "flex",
              flexDirection: "column",
              gap: "15px",
            }}
          >
            {messages.map((msg) => {
              const readers = getReadersForMessage(msg);
              return (
                <div key={msg.id} data-testid="message-item" data-message-id={msg.id} style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
                  <div>
                    <span data-testid="message-sender" style={{ fontWeight: "bold", marginRight: "10px" }}>
                      {msg.sender?.username}
                    </span>
                    <span data-testid="message-content">{msg.content}</span>
                  </div>
                  <div data-testid="message-read-receipts" style={{ fontSize: "12px", color: "#666" }}>
                    {readers.length > 0 && "Read by: "}
                    {readers.map((readerUsername) => (
                      <span key={readerUsername} data-testid="reader-name" data-username={readerUsername} style={{ marginRight: "6px" }}>
                        {readerUsername}
                      </span>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Typing Indicators */}
          <div data-testid="typing-indicators" style={{ height: "20px", fontSize: "14px", color: "#666", fontStyle: "italic" }}>
            {Object.keys(typingUsers).map((username) => (
              <span key={username} data-testid="typing-user-item" data-username={username} style={{ marginRight: "10px" }}>
                {username} is typing...
              </span>
            ))}
          </div>

          {/* Input form */}
          <form onSubmit={handleSendMessage} style={{ display: "flex", gap: "10px" }}>
            <input
              id="message-input"
              data-testid="message-input"
              type="text"
              value={messageContent}
              onChange={(e) => setMessageContent(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Type your message..."
              style={{ flex: 1, padding: "8px" }}
            />
            <button id="send-message-btn" data-testid="send-message-btn" type="submit" style={{ padding: "8px 16px" }}>
              Send
            </button>
          </form>
        </div>

        {/* Sidebar for active users */}
        <div style={{ flex: 1, borderLeft: "1px solid #eee", paddingLeft: "15px" }}>
          <h3>Active Users</h3>
          <div data-testid="active-users-list" style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
            {activeUsers.map((username) => (
              <span key={username} data-testid="active-user-item" data-username={username} style={{ fontSize: "14px", fontWeight: "500" }}>
                ● {username}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { Outlet } from "react-router";
import "./App.css";

export function App() {
  return (
    <main className="flex min-h-screen w-full flex-col bg-neutral-50 text-neutral-800">
      <Outlet />
    </main>
  );
}
